1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { RevealPassword, CopyText } from "@/components/customer/ServerAccess";
5	
6	/**
7	 * The Hostinger-style "your order is being set up" interstitial — shown full
8	 * screen right after a customer pays/deploys, while the VM is still
9	 * PENDING/PROVISIONING, then a one-time success card once it flips to
10	 * RUNNING. Deliberately built as a pure overlay on TOP of the existing
11	 * server-detail page rather than a new route: the page underneath keeps
12	 * rendering (and keeps refreshing via the existing `<AutoRefresh />`) exactly
13	 * as it always has, so this component only ever needs to react to props that
14	 * are already being recomputed every 5s — no new polling loop, no new server
15	 * action.
16	 *
17	 * Visibility rules (see the effect below for the full state machine):
18	 *   - Shows the "provisioning" phase whenever the server is in a transitional
19	 *     status. Sets a sessionStorage flag so a REFRESH mid-provision still
20	 *     shows it (not just the initial mount).
21	 *   - Shows "success" the moment that flag is set AND the status flips to
22	 *     RUNNING — OR, for the case where the server was ALREADY done by the
23	 *     time this page first loaded (real orders provision in under two
24	 *     minutes, but this platform's SANDBOX mode completes instantly), when
25	 *     the URL carries the `purchase=1` marker `reportPurchase` already stamps
26	 *     onto every real paid-order redirect.
27	 *   - Never shown for a customer just casually revisiting an old, already-
28	 *     running server — that's the whole reason for the two gates above
29	 *     instead of "status === RUNNING".
30	 *   - Once dismissed, stays dismissed for this server (sessionStorage),
31	 *     surviving a refresh.
32	 */
33	export function ProvisioningOverlay({
34	  serverId,
35	  status,
36	  transitional,
37	  justPaid,
38	  provisionError,
39	  productLabel,
40	  hostname,
41	  connectAddress,
42	  planName,
43	  osName,
44	  rootPassword,
45	  dashboardHref,
46	}: {
47	  serverId: string;
48	  status: string;
49	  transitional: boolean;
50	  /**
51	   * True only when THIS request's URL carried `?purchase=1` — read server-side
52	   * from `searchParams` and passed down as a plain prop, not re-derived from
53	   * `window.location.search` on the client. `app/dashboard/layout.tsx`'s
54	   * PurchaseTracker also reads `?purchase=1` (to fire the conversion pixel)
55	   * and then strips it via `router.replace()`; a client-side read here loses
56	   * that race unpredictably (confirmed in testing — a lazy `useState`
57	   * initializer still lost it under the App Router's RSC re-render on
58	   * navigation). The server captured the true value from the original
59	   * request before any client-side history mutation could touch it.
60	   */
61	  justPaid: boolean;
62	  provisionError?: string | null;
63	  /** "server" | "game server" | etc — used in copy ("Your ... is live!"). */
64	  productLabel: string;
65	  hostname: string;
66	  /** The connect string to show, e.g. "ssh root@1.2.3.4" or "1.2.3.4:25565" — null while not yet assigned. */
67	  connectAddress: string | null;
68	  planName: string;
69	  osName: string | null;
70	  rootPassword: string | null;
71	  /** Where "Go to your server" sends them — normally just this same page. */
72	  dashboardHref: string;
73	}) {
74	  const storageKey = `nxeon:overlay:${serverId}`;
75	  const [phase, setPhase] = useState<"hidden" | "provisioning" | "success">("hidden");
76	  const mountedAtRef = useRef<number | null>(null);
77	  // Real infra provisions in well under this — it's purely a perceived-progress
78	  // floor so the animation never flashes by unreadably fast (e.g. SANDBOX mode,
79	  // which completes instantly), not a claim about how long the real work takes.
80	  const MIN_PROVISIONING_MS = 3200;
81	
82	  useEffect(() => {
83	    let watching = false;
84	    try {
85	      watching = sessionStorage.getItem(storageKey) === "watching";
86	    } catch {
87	      /* storage disabled — degrade to "never show" rather than guess */
88	    }
89	
90	    if (transitional) {
91	      if (mountedAtRef.current == null) mountedAtRef.current = Date.now();
92	      setPhase("provisioning");
93	      try {
94	        sessionStorage.setItem(storageKey, "watching");
95	      } catch {
96	        /* ignore */
97	      }
98	      return;
99	    }
100	
101	    // Not transitional anymore. Only earn a success screen if we were either
102	    // actively watching this order provision, or just landed here from a real
103	    // paid checkout (the sandbox-instant-complete case).
104	    if (status === "RUNNING" && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
105	      const elapsed = mountedAtRef.current ? Date.now() - mountedAtRef.current : MIN_PROVISIONING_MS;
106	      const wait = Math.max(0, MIN_PROVISIONING_MS - elapsed);
107	      const t = setTimeout(() => setPhase("success"), wait);
108	      return () => clearTimeout(t);
109	    }
110	    // ERROR or anything else while we were watching: hand off to the page's
111	    // own ProvisionErrorBanner rather than duplicating retry UI here.
112	    setPhase("hidden");
113	    // eslint-disable-next-line react-hooks/exhaustive-deps
114	  }, [transitional, status]);
115	
116	  function dismiss() {
117	    try {
118	      sessionStorage.setItem(storageKey, "dismissed");
119	    } catch {
120	      /* ignore */
121	    }
122	    setPhase("hidden");
123	  }
124	
125	  if (phase === "hidden") return null;
126	
127	  return (
128	    <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto bg-navy-950/90 p-4 backdrop-blur-md">
129	      <div className="card glow-brand relative w-full max-w-md motion-safe:animate-panel-in">
130	        {phase === "provisioning" ? (
131	          <ProvisioningView productLabel={productLabel} hostname={hostname} />
132	        ) : (
133	          <SuccessView
134	            productLabel={productLabel}
135	            hostname={hostname}
136	            connectAddress={connectAddress}
137	            planName={planName}
138	            osName={osName}
139	            rootPassword={rootPassword}
140	            onDismiss={dismiss}
141	            dashboardHref={dashboardHref}
142	          />
143	        )}
144	      </div>
145	    </div>
146	  );
147	}
148	
149	const PROVISION_STEPS = [
150	  "Allocating your server…",
151	  "Configuring the network…",
152	  "Booting the operating system…",
153	  "Almost there…",
154	];
155	
156	function ProvisioningView({ productLabel, hostname }: { productLabel: string; hostname: string }) {
157	  // Purely cosmetic, time-based step text — there is no real per-step signal
158	  // from the provisioning worker (it reports one status, not a progress feed),
159	  // so this never claims to track a specific backend action. It only exists
160	  // so a ~30-90s wait doesn't read as a frozen screen.
161	  const [stepIndex, setStepIndex] = useState(0);
162	  useEffect(() => {
163	    const id = setInterval(() => {
164	      setStepIndex((i) => Math.min(i + 1, PROVISION_STEPS.length - 1));
165	    }, 3500);
166	    return () => clearInterval(id);
167	  }, []);
168	
169	  return (
170	    <div className="flex flex-col items-center p-8 text-center">
171	      <div className="relative mb-6 flex h-20 w-20 items-center justify-center">
172	        <span className="absolute inset-0 rounded-full bg-brand-500/20 blur-xl motion-safe:animate-ring-glow" />
173	        <svg viewBox="0 0 80 80" className="absolute inset-0 h-full w-full motion-safe:animate-orbit-spin" aria-hidden>
174	          <circle cx="40" cy="40" r="34" fill="none" stroke="url(#nxeon-orbit-grad)" strokeWidth="4" strokeLinecap="round" strokeDasharray="60 200" />
175	          <defs>
176	            <linearGradient id="nxeon-orbit-grad" x1="0" y1="0" x2="80" y2="80">
177	              <stop offset="0%" stopColor="var(--color-brand-500)" />
178	              <stop offset="100%" stopColor="var(--color-accent-cyan)" />
179	            </linearGradient>
180	          </defs>
181	        </svg>
182	        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className="relative h-8 w-8 text-brand-200">
183	          <rect x="3" y="4" width="18" height="7" rx="1.5" />
184	          <rect x="3" y="13" width="18" height="7" rx="1.5" />
185	          <path d="M7 7.5h.01M7 16.5h.01" />
186	        </svg>
187	      </div>
188	      <h2 className="text-lg font-semibold text-white">Setting up your {productLabel}</h2>
189	      <p className="mt-1 text-sm text-slate-400">
190	        <span className="font-mono text-slate-300">{hostname}</span> is being provisioned.
191	      </p>
192	      <p className="mt-4 min-h-[1.25rem] text-sm text-brand-200 transition-opacity">{PROVISION_STEPS[stepIndex]}</p>
193	      <p className="mt-6 text-xs text-slate-500">
194	        This usually takes under two minutes. Feel free to leave this tab — we&apos;ll have it ready when you&apos;re back.
195	      </p>
196	    </div>
197	  );
198	}
199	
200	function SuccessView({
201	  productLabel,
202	  hostname,
203	  connectAddress,
204	  planName,
205	  osName,
206	  rootPassword,
207	  onDismiss,
208	  dashboardHref,
209	}: {
210	  productLabel: string;
211	  hostname: string;
212	  connectAddress: string | null;
213	  planName: string;
214	  osName: string | null;
215	  rootPassword: string | null;
216	  onDismiss: () => void;
217	  dashboardHref: string;
218	}) {
219	  return (
220	    <div className="p-8">
221	      <div className="flex flex-col items-center text-center">
222	        <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-emerald-500/15 motion-safe:animate-check-pop">
223	          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" className="h-8 w-8 text-emerald-400">
224	            <path
225	              d="M5 12.5l4.5 4.5L19 7"
226	              pathLength={24}
227	              strokeDasharray={24}
228	              className="motion-safe:animate-check-draw"
229	            />
230	          </svg>
231	        </div>
232	        <h2 className="text-lg font-semibold text-white">Your {productLabel} is live!</h2>
233	        <p className="mt-1 text-sm text-slate-400">
234	          <span className="font-mono text-slate-300">{hostname}</span> deployed successfully.
235	        </p>
236	      </div>
237	
238	      <dl className="mt-6 space-y-2 rounded-xl border border-white/[0.07] bg-white/[0.02] p-4 text-sm">
239	        <div className="flex items-center justify-between gap-3">
240	          <dt className="text-slate-500">Plan</dt>
241	          <dd className="text-slate-200">{planName}</dd>
242	        </div>
243	        {osName && (
244	          <div className="flex items-center justify-between gap-3">
245	            <dt className="text-slate-500">Image</dt>
246	            <dd className="text-slate-200">{osName}</dd>
247	          </div>
248	        )}
249	        {connectAddress && (
250	          <div className="flex items-center justify-between gap-3">
251	            <dt className="text-slate-500">Connect</dt>
252	            <dd className="flex items-center gap-2 font-mono text-xs text-slate-200">
253	              {connectAddress}
254	              <CopyText text={connectAddress} />
255	            </dd>
256	          </div>
257	        )}
258	        {rootPassword && (
259	          <div className="flex items-center justify-between gap-3">
260	            <dt className="text-slate-500">Root password</dt>
261	            <dd>
262	              <RevealPassword password={rootPassword} />
263	            </dd>
264	          </div>
265	        )}
266	      </dl>
267	
268	      <div className="mt-6 flex items-center justify-center gap-3">
269	        <a href={dashboardHref} onClick={onDismiss} className="btn-deploy w-full justify-center py-3 text-sm">
270	          Go to your {productLabel}
271	          <span className="dep-arrow">→</span>
272	        </a>
273	      </div>
274	    </div>
275	  );
276	}
