59	function fmtUptime(seconds: number): string {
60	  if (!seconds || seconds <= 0) return "—";
61	  const d = Math.floor(seconds / 86400);
62	  const h = Math.floor((seconds % 86400) / 3600);
63	  const m = Math.floor((seconds % 3600) / 60);
64	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
65	}
66	
67	type LiveStats = {
68	  cpu?: number;
69	  mem?: number;
70	  maxmem?: number;
71	  uptime?: number;
72	  netin?: number;
73	  netout?: number;
74	} | null;
75	
76	export default async function ServerPage({
77	  params,
78	  searchParams,
79	}: {
80	  params: Promise<{ id: string }>;
81	  searchParams: Promise<{ tab?: string; purchase?: string }>;
82	}) {
83	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
84	  const user = await requireUser();
85	  const server = await db.server.findUnique({
86	    where: { id },
87	    include: {
88	      plan: true,
89	      osTemplate: true,
90	      project: true,
91	      portForwards: { orderBy: { publicPort: "asc" } },
92	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
93	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
94	      dedicatedIp: true,
95	      node: true,
96	      // Needed to price a renewal correctly: a game server bills its game plan's
97	      // flat price, not the base VPS plan's term price.
98	      gamePlan: true,
99	    },
100	  });
101	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
102	
103	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
104	  // display value through the decrypt fallback (legacy plaintext rows still work).
105	  const rootPassword = serverRootPassword(server);
106	
107	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct] = await Promise.all([
108	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
109	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
110	    db.osTemplate.findMany({
111	      where: { active: true, category: "PLAIN_OS" },
112	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
113	    }),
114	    extraDiskPerGbCents(),
115	    backupPlusMonthlyCents(),
116	    // Live annual discount — feeds the "Renew now" quote below AND the resize
117	    // pickers, so an annual server's renewal/upgrade/downgrade all price against the
118	    // same rate it was sold at.
119	    annualDiscountPct(),
120	  ]);
121	
122	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
123	  const owner =
124	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
125	  const renewTaxCtx = await taxContextForUser(owner);
126	
127	  // What "Renew now" will actually charge, priced through the SAME function the
128	  // action charges through, so the button cannot quote one figure and take
129	  // another. See lib/renewal-quote.ts for the incident.
130	  const renewQuote = renewalQuote(
131	    {
132	      termMonths: server.termMonths,
133	      extraDiskGB: server.extraDiskGB,
134	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
135	      // A game server is sold at its game plan's flat price, NOT the base VPS
136	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
137	      // a $4.99 product.
138	      gamePlan: server.gamePlan
139	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
140	        : null,
141	      dedicatedIp: server.dedicatedIp,
142	      backupTier: server.backupTier,
143	    },
144	    {
145	      ipMonthlyCents: server.dedicatedIp ? await dedicatedIpMonthlyCents() : 0,
146	      extraDiskPerGbCents: extraDiskPriceCents,
147	      backupPlusCents,
148	      annualDiscountPct: annualPct,
149	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
150	      // now quote are tax-inclusive, matching what renewNow charges.
151	      taxRatePercent: renewTaxCtx.ratePercent,
152	    },
153	  );
154	
155	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
156	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
157	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
158	
159	  const publicIp = process.env.PUBLIC_IP ?? "";
160	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
161	  const busy =
162	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
163	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
164	
165	  let live: LiveStats = null;
166	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
167	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
168	  let pveUnavailable = false;
169	
170	  if (server.vmid && steady) {
171	    const results = await Promise.allSettled([
172	      vmStatus(server.vmid),
173	      listSnapshots(server.vmid),
174	      listBackups(server.vmid),
175	    ]);
176	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
177	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
178	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
179	    pveUnavailable = results.some((r) => r.status === "rejected");
