457	export async function provisionHostingAccount(accountId: string): Promise<void> {
458	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
459	  if (!account || account.status !== "PENDING") return;
460	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
461	
462	  if (SANDBOX || !ENABLED) {
463	    if (SANDBOX) {
464	      const pw = strongPassword();
465	      const active = await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
466	      await notifyHostingPartner(active);
467	    } else {
468	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
469	    }
470	    return;
471	  }
472	
473	  try {
474	    const allowed = planLimits(account.plan).phpVersions;
475	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
476	    const sftpPassword = strongPassword();
477	    const conn = await connectNode(account.node);
478	    try {
479	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
480	    } finally {
481	      try { conn.end(); } catch { /* */ }
482	    }
483	    const active = await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
484	    await notifyHostingPartner(active);
485	    // Issue the real cert NOW instead of waiting up to a full sweep interval. A free
486	    // subdomain resolves via the *.sites wildcard the instant it's live, so certbot
487	    // succeeds immediately; a custom domain simply isn't pointed yet and is skipped
488	    // (the periodic sweep catches it once DNS lands). Best-effort — never fail a
489	    // completed provision because HTTPS issuance had a transient hiccup.
490	    await hostingSslSweep().catch((e) => console.error(`[hosting] post-provision SSL issue failed for ${account.id}`, e));
491	  } catch (e) {
492	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
493	  }
494	}
