6	/**
7	 * The Hostinger-style "your order is being set up" interstitial — shown full
8	 * screen right after a customer pays/deploys, while the VM is still
9	 * PENDING/PROVISIONING, then a one-time success card once it flips to
10	 * RUNNING. Deliberately built as a pure overlay on TOP of the existing
11	 * server-detail page rather than a new route: the page underneath keeps
12	 * rendering (and keeps refreshing via the existing `<AutoRefresh />`) exactly
13	 * as it always has, so this component only ever needs to react to props that
14	 * are already being recomputed every 5s — no new polling loop, no new server
15	 * action.
16	 *
17	 * Visibility rules (see the effect below for the full state machine):
18	 *   - Shows the "provisioning" phase whenever the server is in a transitional
19	 *     status. Sets a sessionStorage flag so a REFRESH mid-provision still
20	 *     shows it (not just the initial mount).
21	 *   - Shows "success" the moment that flag is set AND the status flips to
22	 *     RUNNING — OR, for the case where the server was ALREADY done by the
23	 *     time this page first loaded (real orders provision in under two
24	 *     minutes, but this platform's SANDBOX mode completes instantly), when
25	 *     the URL carries the `purchase=1` marker `reportPurchase` already stamps
26	 *     onto every real paid-order redirect.
27	 *   - Never shown for a customer just casually revisiting an old, already-
28	 *     running server — that's the whole reason for the two gates above
29	 *     instead of "status === RUNNING".
30	 *   - Once dismissed, stays dismissed for this server (sessionStorage),
31	 *     surviving a refresh.
32	 */
33	export function ProvisioningOverlay({
34	  serverId,
35	  status,
36	  transitional,
37	  justPaid,
38	  provisionError,
39	  productLabel,
40	  hostname,
41	  connectAddress,
42	  planName,
43	  osName,
44	  rootPassword,
45	  rootPasswordLabel,
46	  extraInfo,
47	  readyStatus = "RUNNING",
48	  liveStep = null,
49	  liveStepActive = false,
50	  dashboardHref,
51	}: {
52	  serverId: string;
53	  status: string;
54	  transitional: boolean;
55	  /**
56	   * True only when THIS request's URL carried `?purchase=1` — read server-side
57	   * from `searchParams` and passed down as a plain prop, not re-derived from
58	   * `window.location.search` on the client. `app/dashboard/layout.tsx`'s
59	   * PurchaseTracker also reads `?purchase=1` (to fire the conversion pixel)
60	   * and then strips it via `router.replace()`; a client-side read here loses
61	   * that race unpredictably (confirmed in testing — a lazy `useState`
62	   * initializer still lost it under the App Router's RSC re-render on
63	   * navigation). The server captured the true value from the original
64	   * request before any client-side history mutation could touch it.
65	   */
66	  justPaid: boolean;
67	  provisionError?: string | null;
68	  /** "server" | "game server" | "hosting account" | etc — used in copy ("Your ... is live!"). */
69	  productLabel: string;
70	  hostname: string;
71	  /** The connect string to show, e.g. "ssh root@1.2.3.4" or "1.2.3.4:25565" — null while not yet assigned. */
72	  connectAddress: string | null;
73	  planName: string;
74	  osName: string | null;
75	  rootPassword: string | null;
76	  /** Label for the `rootPassword` row — defaults to "Root password" (VPS/game). Shared
77	   *  Hosting has no root password; pass "SFTP password" there instead of inventing a
78	   *  VPS-shaped field that doesn't exist for that product. */
79	  rootPasswordLabel?: string;
80	  /** Extra product-specific rows appended to the success card's info panel (e.g.
81	   *  Shared Hosting's "SFTP username" / "Website" — fields a VPS has no analogue
82	   *  for), rather than forcing every product into VPS-shaped fields. */
83	  extraInfo?: { label: string; value: string; href?: string }[];
84	  /** The status value that means "done, show the success card" — "RUNNING" for a
85	   *  VPS/game server, "ACTIVE" for a Shared Hosting account. */
86	  readyStatus?: string;
87	  /** Real (never fake/invented) current-step label, e.g. "Cloning your server…" or
88	   *  "Installing WordPress…" — sourced from lib/provisioning-step.ts. Replaces the
89	   *  cosmetic time-based cycling text in the provisioning view when present; null
90	   *  falls back to that cosmetic text (no real signal available yet). */
91	  liveStep?: string | null;
92	  /** True while a real, product-specific step is still in progress even though
93	   *  `transitional` (account/server status) has already gone false — e.g. Shared
94	   *  Hosting's account is ACTIVE but a just-ordered WordPress install is still
95	   *  running as a queued task. Only ever extends the provisioning view while this
96	   *  session was already watching (or just paid) — see the effect below — so a
97	   *  LATER, casual action (installing an app months on) never hijacks the screen. */
98	  liveStepActive?: boolean;
99	  /** Where "Go to your server" sends them — normally just this same page. */
100	  dashboardHref: string;
101	}) {
102	  const storageKey = `nxeon:overlay:${serverId}`;
103	  const [phase, setPhase] = useState<"hidden" | "provisioning" | "success">("hidden");
104	  const mountedAtRef = useRef<number | null>(null);
105	  // Real infra provisions in well under this — it's purely a perceived-progress
106	  // floor so the animation never flashes by unreadably fast (e.g. SANDBOX mode,
107	  // which completes instantly), not a claim about how long the real work takes.
108	  const MIN_PROVISIONING_MS = 3200;
109	
110	  useEffect(() => {
111	    let watching = false;
112	    try {
113	      watching = sessionStorage.getItem(storageKey) === "watching";
114	    } catch {
115	      /* storage disabled — degrade to "never show" rather than guess */
116	    }
117	
118	    if (transitional) {
119	      if (mountedAtRef.current == null) mountedAtRef.current = Date.now();
120	      setPhase("provisioning");
121	      try {
122	        sessionStorage.setItem(storageKey, "watching");
123	      } catch {
124	        /* ignore */
125	      }
126	      return;
127	    }
128	
129	    // Not transitional anymore (by the base status alone). Before deciding this is
130	    // done, check for a real, product-specific follow-on step still running — e.g.
131	    // Shared Hosting's account just flipped ACTIVE but a WordPress install queued
132	    // at order time is still processing. Gated on watching/justPaid, same as the
133	    // block above: this must never resurrect the full-screen takeover for a LATER,
134	    // casual action (installing an app months after purchase) — only for a follow-
135	    // on step that belongs to the SAME order this session was already watching.
136	    if (liveStepActive && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
137	      setPhase("provisioning");
138	      return;
139	    }
140	
141	    // Only earn a success screen if we were either actively watching this order
142	    // provision, or just landed here from a real paid checkout (the
143	    // sandbox-instant-complete case).
144	    if (status === readyStatus && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
145	      const elapsed = mountedAtRef.current ? Date.now() - mountedAtRef.current : MIN_PROVISIONING_MS;
146	      const wait = Math.max(0, MIN_PROVISIONING_MS - elapsed);
147	      const t = setTimeout(() => setPhase("success"), wait);
148	      return () => clearTimeout(t);
149	    }
150	    // ERROR or anything else while we were watching: hand off to the page's
151	    // own ProvisionErrorBanner rather than duplicating retry UI here.
152	    setPhase("hidden");
153	    // eslint-disable-next-line react-hooks/exhaustive-deps
154	  }, [transitional, status, liveStepActive, readyStatus]);
155	
156	  function dismiss() {
157	    try {
158	      sessionStorage.setItem(storageKey, "dismissed");
159	    } catch {
160	      /* ignore */
161	    }
162	    setPhase("hidden");
163	  }
164	
165	  if (phase === "hidden") return null;
166	
167	  return (
168	    <div className="fixed inset-0 z-[100] flex items-center justify-center overflow-y-auto bg-navy-950/90 p-4 backdrop-blur-md">
169	      <div className="card glow-brand relative w-full max-w-md motion-safe:animate-panel-in">
170	        {phase === "provisioning" ? (
171	          <ProvisioningView productLabel={productLabel} hostname={hostname} liveStep={liveStep} />
172	        ) : (
173	          <SuccessView
174	            productLabel={productLabel}
175	            hostname={hostname}
176	            connectAddress={connectAddress}
177	            planName={planName}
178	            osName={osName}
179	            rootPassword={rootPassword}
180	            rootPasswordLabel={rootPasswordLabel}
181	            extraInfo={extraInfo}
182	            onDismiss={dismiss}
183	            dashboardHref={dashboardHref}
184	          />
185	        )}
186	      </div>
187	    </div>
188	  );
189	}
190	
191	const PROVISION_STEPS = [
192	  "Allocating your server…",
193	  "Configuring the network…",
194	  "Booting the operating system…",
195	  "Almost there…",
196	];
