206	   *  on ProvisioningOverlay. Null falls back to the cosmetic cycling text below. */
207	  liveStep?: string | null;
208	}) {
209	  // Purely cosmetic, time-based step text — the FALLBACK for whichever products
210	  // (or moments) have no real per-step signal from the provisioning worker (it
211	  // reports one status, not a progress feed). Only exists so a ~30-90s wait
212	  // doesn't read as a frozen screen. Skipped entirely once `liveStep` is real.
213	  const [stepIndex, setStepIndex] = useState(0);
214	  useEffect(() => {
215	    if (liveStep) return;
216	    const id = setInterval(() => {
217	      setStepIndex((i) => Math.min(i + 1, PROVISION_STEPS.length - 1));
218	    }, 3500);
219	    return () => clearInterval(id);
220	  }, [liveStep]);
221	  const displayStep = liveStep || PROVISION_STEPS[stepIndex];
222	
223	  return (
224	    <div className="flex flex-col items-center p-8 text-center">
